      x.withCredentials = true
      x.timeout = 180000
      x.setRequestHeader('X-Sporta-Admin', '1')
      x.setRequestHeader('Content-Type', 'application/json')
      if (x.upload) x.upload.onprogress = function (e) { if (e.lengthComputable) onProgress(e.loaded / e.total) }
