    all.addEventListener('click', function () { visible().forEach(function (v) { S.sel[v.id] = 1 }); S.confirm = false; draw() })
    var none = el('button', 'spt-btn', t('untick')); none.type = 'button'; none.setAttribute('data-spt-bulk', 'none')
