    row('رد المتجر', t.shop_reply)
    if (ok) row('صياغة الذكاء الاصطناعي', t.reply)
    if (ai.status !== 'off') row('النموذج', ai.model)
    if (typeof ai.ms === 'number' && ai.status !== 'off') row('الوقت', ai.ms + ' ms')
