    '.sai-verdict[data-ok="1"]{color:var(--sai-ok)}',
    '.sai-dl{display:grid;gap:.25rem .75rem;margin:0}',
    '@container (min-width:640px){.sai-dl{grid-template-columns:12rem minmax(0,1fr)}}',
