    function put(t) { t = String(t).replace(/[^A-Za-z0-9_؀-ۿ]/g, ''); if (t && tags.indexOf('#' + t) < 0) tags.push('#' + t) }
    var bEn = brand[0].replace(/[^A-Za-z0-9]/g, ''), bAr = brand[1].replace(/\s+/g, '_')
