          if (!r.ok) { put('tags-' + pg[0], 'fail', pg[1] + ': share tags', 'The page answered HTTP ' + (r.status || 'nothing') + '.', 'Open the page in a browser. If it loads there, run the checks again in a minute.'); return }
          var t = readTags(r.text), missing = []
