    '.ssoc-needs>li{display:grid;gap:.5rem;padding:.75rem;border:1px solid var(--sc-line);border-radius:.75rem;background:var(--sc-soft)}',
    '.ssoc-needs h3{margin:0;font-size:.9375rem;font-weight:700}',
