    pw.type = 'password'
    pw.required = true
    pw.autocomplete = 'current-password'
    pw.spellcheck = false
    pw.setAttribute('autocapitalize', 'none')
    pw.setAttribute('dir', 'ltr')
    pwLabel.htmlFor = pw.id
    pwField.appendChild(pwLabel)
    pwField.appendChild(pw)

