  document.addEventListener('click', soon, true)
  document.addEventListener('keyup', function (e) { if (e.key === 'Enter' || e.key === ' ') soon() }, true)
  window.addEventListener('popstate', soon)
  document.addEventListener('visibilitychange', tick)
