      fact(dl, t('alts'), ['ar', 'en', 'x-default'].map(function (k) { return k + (f.alts[k] ? ' ✓' : ' ✗') }).join('  '))
      fact(dl, t('social'), ['og:title', 'og:description', 'og:image'].map(function (k) { return k.slice(3) + (f.og[k] ? ' ✓' : ' ✗') }).join('  '))
